<?php require_once __DIR__.'/config/config.php';require_login();$uid=current_user_id();$page_title='Messages';$to=(int)($_GET['to']??0);if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$to=(int)($_POST['receiver_id']??0);$body=trim($_POST['body']??'');$s=$conn->prepare('SELECT id FROM users WHERE id=?');$s->bind_param('i',$to);$s->execute();if($to===$uid||!$s->get_result()->fetch_row()||$body===''||mb_strlen($body)>3000)flash('Unable to send message.','error');else{$s=$conn->prepare('INSERT INTO messages(sender_id,receiver_id,body) VALUES(?,?,?)');$s->bind_param('iis',$uid,$to,$body);$s->execute();flash('Message sent!');}redirect('messages.php?to='.$to);}$recipient=null;$messages=null;if($to>0){$s=$conn->prepare('SELECT id,username,display_name FROM users WHERE id=?');$s->bind_param('i',$to);$s->execute();$recipient=$s->get_result()->fetch_assoc();if($recipient){$s=$conn->prepare('SELECT * FROM messages WHERE (sender_id=? AND receiver_id=?) OR (sender_id=? AND receiver_id=?) ORDER BY created_at ASC LIMIT 200');$s->bind_param('iiii',$uid,$to,$to,$uid);$s->execute();$messages=$s->get_result();$s=$conn->prepare('UPDATE messages SET is_read=1 WHERE sender_id=? AND receiver_id=?');$s->bind_param('ii',$to,$uid);$s->execute();}}$s=$conn->prepare("SELECT u.id,u.username,u.display_name,u.avatar_url,SUM(CASE WHEN m.sender_id=u.id AND m.is_read=0 THEN 1 ELSE 0 END) AS unread FROM users u JOIN messages m ON (m.sender_id=u.id AND m.receiver_id=?) OR (m.receiver_id=u.id AND m.sender_id=?) WHERE u.id<>? GROUP BY u.id,u.username,u.display_name,u.avatar_url ORDER BY u.display_name");$s->bind_param('iii',$uid,$uid,$uid);$s->execute();$contacts=$s->get_result();require __DIR__.'/includes/header.php';?><div class="page-heading"><p class="eyebrow">PRIVATE CONVERSATIONS</p><h1>Messages ♡</h1></div><div class="messages-layout card"><aside class="conversation-list"><h3>Conversations</h3><?php while($u=$contacts->fetch_assoc()):?><a class="<?=($to==(int)$u['id']?'active':'')?>" href="messages.php?to=<?=(int)$u['id']?>"><?php if((int)$u['unread']>0):?><span class="nav-count convo-count"><?=badge_text((int)$u['unread'])?></span><?php endif;?><?=e($u['display_name'])?><small>@<?=e($u['username'])?></small></a><?php endwhile;?><p class="muted tiny">Visit a member's RP profile and select Message to start a chat.</p></aside><section class="chat-panel"><?php if(!$recipient):?><div class="empty-state">Choose a conversation to get started. ♡</div><?php else:?><div class="chat-header"><strong><?=e($recipient['display_name'])?></strong><small>@<?=e($recipient['username'])?></small></div><div class="chat-messages"><?php while($m=$messages->fetch_assoc()):?><div class="bubble <?=((int)$m['sender_id']===$uid?'mine':'theirs')?>"><?=nl2br(e($m['body']))?><small><?=e($m['created_at'])?></small></div><?php endwhile;?></div><form method="post" class="chat-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="receiver_id" value="<?=(int)$recipient['id']?>"><input name="body" maxlength="3000" required placeholder="Write a message..."><button class="btn">Send ♡</button></form><?php endif;?></section></div><?php require __DIR__.'/includes/footer.php';?>